# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KEHF SURESİ KISSALARI VE KUR\'AN KISSALARININ GENEL ÖZELLİKLERİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Kehf Suresinde Yer Alan Kıssalar</text>\n  <rect x="32" y="80" width="296" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="180" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">1. Ashâbü\'l-Kehf (أَصْحَابُ الْكَهْفِ - Mağara Arkadaşları)</text>\n  <text x="180" y="114" text-anchor="middle" font-size="10" fill="#1e3a8a">Tevhid inancını korumak için mağaraya sığınan gençler (İnanç sınaması)</text>\n  <rect x="32" y="130" width="296" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="180" y="148" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">2. Hz. Musa ve Salih Kul (قِصَّةُ مُوسَى وَالْعَبْدِ الصَّالِحِ)</text>\n  <text x="180" y="164" text-anchor="middle" font-size="10" fill="#1e3a8a">İlim yolculuğu, sabır, tevazu ve olayların iç yüzü (İlim sınaması)</text>\n  <rect x="32" y="180" width="296" height="48" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="180" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">3. Bahçe Sahibi ve Zülkarneyn Kıssaları</text>\n  <text x="180" y="214" text-anchor="middle" font-size="10" fill="#1e3a8a">Servet ve iktidar karşısında şükür ve adalet bilinci</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">Kur\'an Kıssalarının Amaçları (أَهْدَافُ الْقَصَصِ)</text>\n  <text x="374" y="94" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">الْعِبْرَةُ وَالْمَوْعِظَةُ (İbret ve Öğüt):</tspan> Geçmiş milletlerin</text>\n  <text x="384" y="109" font-size="10" fill="#14532d">ve peygamberlerin hayatından ders çıkarmak (Yûsuf, 111).</text>\n  <text x="374" y="131" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">تَثْبِيتُ الْفُؤَادِ (Kalbi Pekiştirmek):</tspan> Hz. Peygamber\'in</text>\n  <text x="384" y="146" font-size="10" fill="#14532d">ve müminlerin azmini ve sabrını güçlendirmek (Hûd, 120).</text>\n  <text x="374" y="168" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">تَحْقِيقُ التَّوْحِيدِ (Tevhidi Yerleştirmek):</tspan> Tüm peygamberlerin</text>\n  <text x="384" y="183" font-size="10" fill="#14532d">ortak mesajı olan Allah\'ın birliğini kanıtlamak.</text>\n  <rect x="374" y="196" width="292" height="32" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="520" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Kur\'an kıssaları kurgu değil, mutlak hakikattir (الْحَقّ)!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">DİL BİLGİSİ: SÜLÂSÎ MÜCERRED VE MEZÎD FİİLLER (الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ)</text>\n  <rect x="20" y="46" width="315" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="177" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">1. Sülâsî Mücerred Fiil (الثُّلَاثِيُّ الْمُجَرَّدُ)</text>\n  <text x="32" y="92" font-size="10.5" fill="#78350f">• Mazisinde yalnız <tspan font-weight="bold">3 asli (kök) harf</tspan> bulunan,</text>\n  <text x="40" y="107" font-size="10.5" fill="#78350f">ek harf almamış yalın fiildir (<tspan font-weight="bold">فَعَلَ / فَعِلَ / فَعُلَ</tspan>).</text>\n  <rect x="32" y="120" width="290" height="106" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="44" y="140" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">صَبَرَ (sabera):</tspan> Sabretti</text>\n  <text x="44" y="158" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">خَرَقَ (haraka):</tspan> Deldi (gemiyi deldi)</text>\n  <text x="44" y="176" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">قَتَلَ (katele):</tspan> Öldürdü</text>\n  <text x="44" y="194" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">عَلِمَ (alime):</tspan> Bildi  ·  <tspan font-weight="bold">حَمَلَ (hamele):</tspan> Taşıdı</text>\n  <text x="44" y="212" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">غَرِقَ (garika):</tspan> Boğuldu  ·  <tspan font-weight="bold">نَصَرَ (nasara):</tspan> Yardım etti</text>\n  <rect x="355" y="46" width="325" height="194" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">2. Sülâsî Mezîd Fiil (الثُّلَاثِيُّ الْمَزِيدُ)</text>\n  <text x="367" y="92" font-size="10.5" fill="#581c87">• Üç kök harfine <tspan font-weight="bold">1, 2 veya 3 harf</tspan> eklenmiş fiildir:</text>\n  <rect x="367" y="104" width="300" height="122" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="377" y="123" font-size="10" fill="#581c87">• <tspan font-weight="bold">1 Harf Ekli:</tspan> <tspan font-weight="bold">أَفْعَلَ</tspan> (أَرْسَلَ، أَقَامَ، أَرَادَ) · <tspan font-weight="bold">فَعَّلَ</tspan> (عَلَّمَ، بَشَّرَ)</text>\n  <text x="385" y="138" font-size="10" fill="#581c87"><tspan font-weight="bold">فَاعَلَ</tspan> (سَافَرَ، جَاهَدَ، حَاوَرَ)</text>\n  <text x="377" y="158" font-size="10" fill="#581c87">• <tspan font-weight="bold">2 Harf Ekli:</tspan> <tspan font-weight="bold">اِنْفَعَلَ</tspan> (اِنْطَلَقَ - yola koyuldu)</text>\n  <text x="385" y="173" font-size="10" fill="#581c87"><tspan font-weight="bold">اِفْتَعَلَ</tspan> (اِتَّخَذَ، اِجْتَمَعَ) · <tspan font-weight="bold">تَفَعَّلَ</tspan> (تَعَلَّمَ) · <tspan font-weight="bold">تَفَاعَلَ</tspan> (تَعَاوَنَ)</text>\n  <text x="377" y="193" font-size="10" fill="#581c87">• <tspan font-weight="bold">3 Harf Ekli:</tspan> <tspan font-weight="bold">اِسْتَفْعَلَ</tspan> (اِسْتَطَاعَ - güç yetirdi,</text>\n  <text x="385" y="208" font-size="10" fill="#581c87">اِسْتَغْفَرَ - bağışlanma diledi, اِسْتَطْعَمَا - yemek istediler)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ULÜ\'L-AZM PEYGAMBERLERLE İLGİLİ ÖRNEK ARAPÇA CÜMLELER (2. ÜNİTE ÖZETİ)</text>\n  <rect x="25" y="46" width="650" height="194" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">أُولُو الْعَزْمِ مِنَ الرُّسُلِ (Ulü\'l-Azm Peygamberler: Nûh, İbrâhîm, Mûsâ, Îsâ, Muhammed)</text>\n  <rect x="40" y="80" width="620" height="28" rx="5" fill="#ffffff" stroke="#93c5fd"/>\n  <text x="350" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">1. دَعَا نُوحٌ (ع) قَوْمَهُ إِلَى التَّوْحِيدِ وَصَنَعَ السَّفِينَةَ. (Hz. Nûh kavmini tevhide çağırdı ve gemiyi yaptı.)</text>\n  <rect x="40" y="114" width="620" height="28" rx="5" fill="#ffffff" stroke="#93c5fd"/>\n  <text x="350" y="132" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">2. حَطَّمَ إِبْرَاهِيمُ (ع) الْأَصْنَامَ وَبَنَى الْكَعْبَةَ. (Hz. İbrâhîm putları kırdı ve Kâbe\'yi inşa etti.)</text>\n  <rect x="40" y="148" width="620" height="28" rx="5" fill="#ffffff" stroke="#93c5fd"/>\n  <text x="350" y="166" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">3. أَرْسَلَ اللَّهُ مُوسَى (ع) إِلَى فِرْعَوْنَ وَتَعَلَّمَ مِنَ الْعَبْدِ الصَّالِحِ. (Allah Hz. Mûsâ\'yı Firavun\'a gönderdi...)</text>\n  <rect x="40" y="182" width="620" height="28" rx="5" fill="#ffffff" stroke="#93c5fd"/>\n  <text x="350" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">4. أَنْزَلَ اللَّهُ الْإِنْجِيلَ عَلَى عِيسَى (ع) وَالْقُرْآنَ عَلَى مُحَمَّدٍ (ص). (Allah İncil\'i Îsâ\'ya, Kur\'an\'ı Muhammed\'e indirdi.)</text>\n  <text x="350" y="228" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">فَاصْبِرْ كَمَا صَبَرَ أُولُو الْعَزْمِ مِنَ الرُّسُلِ (Ahkâf, 46/35: Ulü\'l-azm peygamberlerin sabrettiği gibi sabret!)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
